		onContentsChangedListeners.clear();
	}

	@Override
	public CompoundTag serializeNBT(HolderLookup.Provider registries) {
		ListTag nbtTagList = new ListTag();
		nbtTagList.addAll(stackNbts.values());
		CompoundTag nbt = new CompoundTag();
		nbt.put("Items", nbtTagList);
		nbt.putInt("Size", getSlots());
		return nbt;
	}

	public double getStackSizeMultiplier() {
		return maxStackSizeMultiplier;
	}

	@Override
	public ItemStack insertItem(ItemStack stack, boolean simulate) {
		return getSlotTracker().insertItemIntoHandler(this, this::runOnBeforeInsert, this::insertItemInternal, this::triggerSlotOverflowUpgrades,
				this::triggerStorageOverflowUpgrades, stack, simulate);
	}

	@Override
	public ItemStack extractItem(ItemStack stack, boolean simulate) {
