	}

	public void changeSlots(int diff) {
		NonNullList<ItemStack> previousStacks = stacks;
		stacks = NonNullList.withSize(previousStacks.size() + diff, ItemStack.EMPTY);
		for (int slot = 0; slot < previousStacks.size() && slot < stacks.size(); slot++) {
			stacks.set(slot, previousStacks.get(slot));
		}
		initStackNbts();
		saveInventory();
		getSlotTracker().refreshSlotIndexesFrom(this);
	}

	@Override
	public Set<ItemStackKey> getTrackedStacks() {
		initSlotTracker();
		HashSet<ItemStackKey> ret = new HashSet<>(slotTracker.getFullStacks());
		ret.addAll(slotTracker.getPartialStacks());
		return ret;
	}

	@Override
	public void registerTrackingListeners(Consumer<ItemStackKey> onAddStackKey, Consumer<ItemStackKey> onRemoveStackKey, Runnable onAddFirstEmptySlot,
			Runnable onRemoveLastEmptySlot) {
		getSlotTracker().registerListeners(onAddStackKey, onRemoveStackKey, onAddFirstEmptySlot, onRemoveLastEmptySlot);
	}

	@Override
	public void unregisterStackKeyListeners() {
		slotTracker.unregisterStackKeyListeners();
	}

	@Override
	public boolean hasEmptySlots() {
		return slotTracker.hasEmptySlots();
	}

	public InventoryPartitioner getInventoryPartitioner() {
		return inventoryPartitioner;
	}

	public boolean isSlotAccessible(int slot) {
		return !isSlotBlocked.test(slot) && inventoryPartitioner.getPartBySlot(slot).isSlotAccessible(slot);
	}

	public boolean shouldRenderInaccessibleSlotOverlay(int slot) {
		if (isSlotBlocked.test(slot)) {
			return shouldRenderBlockedSlotOverlay.test(slot);
		}
		return inventoryPartitioner.shouldRenderInaccessibleSlotOverlay(slot);
	}

	public void setSlotBlockedPredicate(IntPredicate isSlotBlocked, IntPredicate shouldRenderBlockedSlotOverlay) {
		this.isSlotBlocked = isSlotBlocked;
		this.shouldRenderBlockedSlotOverlay = shouldRenderBlockedSlotOverlay;
		getSlotTracker().refreshSlotIndexesFrom(this);
		onFilterItemsChanged();
	}

	public Set<Integer> getNoSortSlots() {
		return inventoryPartitioner.getNoSortSlots();
	}

	public void onSlotFilterChanged(int slot) {
		inventoryPartitioner.getPartBySlot(slot).onSlotFilterChanged(slot);
	}

	public void registerFilterItemsChangeListener(Consumer<Set<Item>> listener) {
		filterItemsChangeListener = listener;
	}

	public void unregisterFilterItemsChangeListener() {
		filterItemsChangeListener = s -> {
		};
	}

	public void initFilterItems() {
		inventoryPartitioner.getFilterItems().forEach((item, slots) -> slots.forEach(slot -> filterItemSlots.add(slot, item)));
	}

	public void onFilterItemsChanged() {
		slotTracker.refreshSlotIndexesFrom(this);
		if (inventoryPartitioner == null) {
			return;
		}
		filterItemSlots.clear();
		inventoryPartitioner.getFilterItems().forEach((item, slots) -> slots.forEach(slot -> filterItemSlots.add(slot, item)));

		filterItemsChangeListener.accept(filterItemSlots.keySet());
	}

	public Set<Item> getFilterItems() {
		return filterItemSlots.keySet();
	}

	public void onInit() {
		if (inventoryPartitioner == null) {
			return;
		}
		inventoryPartitioner.onInit();
		slotTracker = new ISlotTracker.Noop();
	}

	public void setShouldInsertIntoEmpty(BooleanSupplier shouldInsertIntoEmpty) {
		this.shouldInsertIntoEmpty = shouldInsertIntoEmpty;
		getSlotTracker().setShouldInsertIntoEmpty(shouldInsertIntoEmpty);
	}

	public boolean isInfinite(int slot) {
		return inventoryPartitioner.isInfinite(slot);
	}

	private boolean hasVoidUpgrade() {
		if (!voidUpgradeInfoInitialized) {
			hasVoidUpgrade = !storageWrapper.getUpgradeHandler().getTypeWrappers(VoidUpgradeItem.TYPE).isEmpty();
			voidUpgradeInfoInitialized = true;
		}
		return hasVoidUpgrade;
	}

	@Override
	public boolean isInsertBlocked() {
		if (hasVoidUpgrade()) {
			return false;
		}

		for (int slot = 0; slot < stacks.size(); ++slot) {
			ItemStack stack = stacks.get(slot);
			if (stack.getCount() < getStackLimit(slot, stack)) {
				return false;
			}
		}
		return true;
	}
}

package net.p3pp3rf1y.sophisticatedcore.inventory;

import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.p3pp3rf1y.sophisticatedcore.SophisticatedCore;
import net.p3pp3rf1y.sophisticatedcore.settings.memory.MemorySettingsCategory;
import net.p3pp3rf1y.sophisticatedcore.util.SlotValueMap;

import javax.annotation.Nullable;

import java.util.*;
import java.util.function.BiFunction;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.function.UnaryOperator;

public class InventoryHandlerSlotTracker implements ISlotTracker {
	private final Map<ItemStackKey, Set<Integer>> fullStackSlots = new HashMap<>();
	private final Map<Integer, ItemStackKey> fullSlotStacks = new HashMap<>();
	private final Map<ItemStackKey, Set<Integer>> partiallyFilledStackSlots = new HashMap<>();
	private final Map<Integer, ItemStackKey> partiallyFilledSlotStacks = new HashMap<>();
	private final Map<Item, Set<ItemStackKey>> itemStackKeys = new HashMap<>();
	private final Set<Integer> emptySlots = new TreeSet<>();
	private final MemorySettingsCategory memorySettings;
	private final SlotValueMap<Item> filterItemSlots;
	private Consumer<ItemStackKey> onAddStackKey = sk -> {
	};
	private Consumer<ItemStackKey> onRemoveStackKey = sk -> {
	};

	private Runnable onAddFirstEmptySlot = () -> {
	};
	private Runnable onRemoveLastEmptySlot = () -> {
	};

	private BooleanSupplier shouldInsertIntoEmpty = () -> true;

	public InventoryHandlerSlotTracker(MemorySettingsCategory memorySettings, SlotValueMap<Item> filterItemSlots) {
		this.memorySettings = memorySettings;
		this.filterItemSlots = filterItemSlots;
	}

	@Override
	public void setShouldInsertIntoEmpty(BooleanSupplier shouldInsertIntoEmpty) {
		this.shouldInsertIntoEmpty = shouldInsertIntoEmpty;
	}

	public void addPartiallyFilled(int slot, ItemStack stack) {
		ItemStackKey stackKey = ItemStackKey.of(stack);
		partiallyFilledStackSlots.computeIfAbsent(stackKey, k -> {
			if (!fullStackSlots.containsKey(k)) {
				onAddStackKey.accept(k);
			}
			return new TreeSet<>();
		}).add(slot);
		partiallyFilledSlotStacks.put(slot, stackKey);
		itemStackKeys.computeIfAbsent(stack.getItem(), i -> new HashSet<>()).add(stackKey);
	}

	@Override
	public Set<ItemStackKey> getFullStacks() {
		return fullStackSlots.keySet();
	}

	@Override
	public Set<ItemStackKey> getPartialStacks() {
		return partiallyFilledStackSlots.keySet();
	}

	@Override
	public boolean hasExactStackMemorized(ItemStackKey stackKey) {
		return memorySettings.matchesStackKey(stackKey);
	}

	@Override
	public boolean hasItemMemorizedOrFiltered(Item item) {
		return memorySettings.matchesItem(item) || filterItemSlots.containsValue(item);
	}

	@Override
	public Set<Item> getItems() {
		return itemStackKeys.keySet();
	}

	@Override
	public boolean hasMatchingFullStack(ItemStack stack, Predicate<ItemStack> stackMatcher) {
		Set<ItemStackKey> stackKeys = itemStackKeys.get(stack.getItem());
		if (stackKeys == null || stackKeys.isEmpty()) {
			return false;
		}

		for (ItemStackKey stackKey : stackKeys) {
			if (fullStackSlots.containsKey(stackKey) && stackMatcher.test(stackKey.getStack())) {
				return true;
			}
		}

		return false;
	}

	public void addFull(int slot, ItemStack stack) {
		ItemStackKey stackKey = ItemStackKey.of(stack);
		fullStackSlots.computeIfAbsent(stackKey, k -> {
			if (!partiallyFilledStackSlots.containsKey(k)) {
				onAddStackKey.accept(k);
			}
			return new TreeSet<>();
		}).add(slot);
		fullSlotStacks.put(slot, stackKey);
		itemStackKeys.computeIfAbsent(stack.getItem(), i -> new HashSet<>()).add(stackKey);
	}

	public void removePartiallyFilled(int slot) {
		if (partiallyFilledSlotStacks.containsKey(slot)) {
			ItemStackKey stackKey = partiallyFilledSlotStacks.remove(slot);
			@Nullable
			Set<Integer> partialSlots = partiallyFilledStackSlots.get(stackKey);
			if (partialSlots == null) {
				SophisticatedCore.LOGGER.error("Unstable ItemStack detected in slot tracking: {}",
						() -> stackKey != null ? stackKey.stack().toString() : "null");
			} else {
				partialSlots.remove(slot);
			}
			if (partialSlots == null || partialSlots.isEmpty()) {
				partiallyFilledStackSlots.remove(stackKey);
				if (!fullStackSlots.containsKey(stackKey)) {
					onStackKeyRemoved(stackKey);
				}
			}
		}
	}

	private void removeFull(int slot) {
		if (fullSlotStacks.containsKey(slot)) {
			ItemStackKey stackKey = fullSlotStacks.remove(slot);
			@Nullable
			Set<Integer> fullSlots = fullStackSlots.get(stackKey);
			if (fullSlots == null) {
				SophisticatedCore.LOGGER.error("Unstable ItemStack detected in slot tracking: {}",
						() -> stackKey != null ? stackKey.stack().toString() : "null");
			} else {
				fullSlots.remove(slot);
			}
			if (fullSlots == null || fullSlots.isEmpty()) {
				fullStackSlots.remove(stackKey);
				if (!partiallyFilledStackSlots.containsKey(stackKey)) {
					onStackKeyRemoved(stackKey);
				}
			}
		}
	}

	private void onStackKeyRemoved(ItemStackKey stackKey) {
		itemStackKeys.computeIfPresent(stackKey.getStack().getItem(), (i, stackKeys) -> {
			stackKeys.remove(stackKey);
			return stackKeys;
		});
		if (itemStackKeys.containsKey(stackKey.getStack().getItem()) && itemStackKeys.get(stackKey.getStack().getItem()).isEmpty()) {
			itemStackKeys.remove(stackKey.getStack().getItem());
		}

		onRemoveStackKey.accept(stackKey);
	}

	@Override
	public void removeAndSetSlotIndexes(InventoryHandler inventoryHandler, int slot, ItemStack stack) {
		if (stack.isEmpty()) {
			removePartiallyFilled(slot);
			removeFull(slot);
			if (inventoryHandler.isSlotAccessible(slot)) {
				addEmptySlot(slot);
			}
			return;
		}

		if (emptySlots.contains(slot)) {
			removeEmpty(slot);
		}

		if (isPartiallyFilled(inventoryHandler, slot, stack)) {
			setPartiallyFilled(slot, stack);
		} else {
			setFull(slot, stack);
		}
	}

	private void setFull(int slot, ItemStack stack) {
		boolean containsSlot = fullSlotStacks.containsKey(slot);
		if (!containsSlot || fullSlotStacks.get(slot).hashCodeNotEquals(stack)) {
			if (containsSlot) {
				removeFull(slot);
			}
			addFull(slot, stack);
		}
		if (partiallyFilledSlotStacks.containsKey(slot)) {
			removePartiallyFilled(slot);
		}
	}

	private void setPartiallyFilled(int slot, ItemStack stack) {
		boolean containsSlot = partiallyFilledSlotStacks.containsKey(slot);
		if (!containsSlot || partiallyFilledSlotStacks.get(slot).hashCodeNotEquals(stack)) {
			if (containsSlot) {
				removePartiallyFilled(slot);
			}
			addPartiallyFilled(slot, stack);
		}
		if (fullSlotStacks.containsKey(slot)) {
			removeFull(slot);
		}
	}

	private void removeEmpty(int slot) {
		emptySlots.remove(slot);
		if (emptySlots.isEmpty()) {
			onRemoveLastEmptySlot.run();
		}
	}

	private void set(InventoryHandler inventoryHandler, int slot, ItemStack stack) {
		if (stack.isEmpty()) {
			if (inventoryHandler.isSlotAccessible(slot)) {
				addEmptySlot(slot);
			}
		} else {
			if (isPartiallyFilled(inventoryHandler, slot, stack)) {
				addPartiallyFilled(slot, stack);
			} else {
				addFull(slot, stack);
			}
		}
	}

	private void addEmptySlot(int slot) {
		emptySlots.add(slot);
		if (emptySlots.size() == 1) {
			onAddFirstEmptySlot.run();
		}
	}

	@Override
	public void clear() {
		partiallyFilledStackSlots.clear();
		partiallyFilledSlotStacks.clear();
	}

	@Override
	public void refreshSlotIndexesFrom(InventoryHandler itemHandler) {
		fullStackSlots.keySet().forEach(onRemoveStackKey::accept);
		fullStackSlots.clear();
		fullSlotStacks.clear();
		partiallyFilledStackSlots.keySet().forEach(onRemoveStackKey::accept);
		partiallyFilledStackSlots.clear();
		partiallyFilledSlotStacks.clear();
		itemStackKeys.clear();

		emptySlots.clear();
		onRemoveLastEmptySlot.run();

		for (int slot = 0; slot < itemHandler.getSlots(); slot++) {
			ItemStack stack = itemHandler.getStackInSlot(slot);
			set(itemHandler, slot, stack);
		}
	}

	private boolean isPartiallyFilled(InventoryHandler itemHandler, int slot, ItemStack stack) {
		return stack.getCount() < itemHandler.getStackLimit(slot, stack);
	}

	@Override
	public ItemStack insertItemIntoHandler(InventoryHandler itemHandler, BiFunction<ItemStack, Boolean, ItemStack> beforeInsertHandler,
			IItemHandlerInserter inserter, UnaryOperator<ItemStack> slotOverflowHandler, UnaryOperator<ItemStack> storageOverflowHandler, ItemStack stack,
			boolean simulate) {
		if (emptySlots.isEmpty() && !itemStackKeys.containsKey(stack.getItem())) {
			return stack;
		}

		ItemStackKey stackKey = ItemStackKey.of(stack);
		ItemStack remainingStack = beforeInsertHandler.apply(stack, simulate);
		remainingStack = handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack);
		if (remainingStack.isEmpty()) {
			return remainingStack;
		}
		remainingStack = insertIntoSlotsThatMatchStack(inserter, remainingStack, simulate, stackKey);
		if (!remainingStack.isEmpty()) {
			remainingStack = insertIntoEmptySlots(inserter, remainingStack, simulate);
		}
		if (!remainingStack.isEmpty()) {
			remainingStack = handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack);
		}
		return remainingStack;
	}

	@Override
	public ItemStack insertItemIntoHandler(InventoryHandler itemHandler, BiFunction<ItemStack, Boolean, ItemStack> beforeInsertHandler,
			IItemHandlerInserter inserter, UnaryOperator<ItemStack> slotOverflowHandler, UnaryOperator<ItemStack> storageOverflowHandler, int slot,
			ItemStack stack, boolean simulate) {
		if (simulate) {
			ItemStack remainingStack = beforeInsertHandler.apply(stack, simulate);
			if (remainingStack.isEmpty()) {
				return remainingStack;
			}

			if (fullSlotStacks.containsKey(slot)) {
				return handleOverflow(slotOverflowHandler, storageOverflowHandler, ItemStackKey.of(stack), remainingStack);
			} else if (emptySlots.contains(slot)) {
				if (memorySettings.isSlotSelected(slot) && memorySettings.matchesFilter(slot, stack)) {
					return inserter.insertItem(slot, remainingStack, true);
				} else if (filterItemSlots.getSlots(stack.getItem()).contains(slot)) {
					return inserter.insertItem(slot, remainingStack, true);
				} else if (shouldInsertIntoEmpty.getAsBoolean()) {
					if ((memorySettings.isSlotSelected(slot) && !memorySettings.matchesFilter(slot, stack))
							|| filterItemSlots.containsSlotAndDoesNotMatch(slot, stack.getItem())) {
						ItemStackKey stackKey = ItemStackKey.of(stack);
						return handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack, hasOneFullStackOfItem(stackKey));
					}
					return inserter.insertItem(slot, remainingStack, true);
				}
			} else if (partiallyFilledSlotStacks.containsKey(slot)) {
				if (partiallyFilledSlotStacks.get(slot).hashCode() == ItemStackKey.of(stack).hashCode()) {
					remainingStack = inserter.insertItem(slot, remainingStack, true);
				}
				if (remainingStack.isEmpty()) {
					return remainingStack;
				}
				boolean insertedSomething = remainingStack.getCount() != stack.getCount();
				ItemStackKey stackKey = ItemStackKey.of(remainingStack);
				return handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack,
						insertedSomething || hasOneFullStackOfItem(stackKey));
			}
			return remainingStack;
		}

		return insertItemIntoHandler(itemHandler, beforeInsertHandler, inserter, slotOverflowHandler, storageOverflowHandler, stack, simulate);
	}

	@Override
	public ItemStack extractItemFromHandler(InventoryHandler inventoryHandler, IItemHandlerExtractor extractItemInternal, ItemStack stack, boolean simulate) {
		if (partiallyFilledSlotStacks.isEmpty() && fullSlotStacks.isEmpty()) {
			return ItemStack.EMPTY;
		}

		ItemStackKey stackKey = ItemStackKey.of(stack);
		int extracted = 0;

		Set<Integer> slots = partiallyFilledStackSlots.get(stackKey);
		if (slots != null && !slots.isEmpty()) {
			int originalSize = slots.size();
			int i = 0;
			while (partiallyFilledStackSlots.get(stackKey) != null && !partiallyFilledStackSlots.get(stackKey).isEmpty() && i++ < originalSize) {
				int matchingSlot = partiallyFilledStackSlots.get(stackKey).iterator().next();
				extracted += extractItemInternal.extractItem(matchingSlot, stack.getCount() - extracted, simulate).getCount();
				if (extracted >= stack.getCount()) {
					break;
				}
			}
		}

		slots = fullStackSlots.get(stackKey);
		if (slots != null && !slots.isEmpty() && stack.getCount() > extracted) {
			int originalSize = slots.size();
			int i = 0;
			while (fullStackSlots.get(stackKey) != null && !fullStackSlots.get(stackKey).isEmpty() && i++ < originalSize) {
				int matchingSlot = fullStackSlots.get(stackKey).iterator().next();
				extracted += extractItemInternal.extractItem(matchingSlot, stack.getCount() - extracted, simulate).getCount();
				if (extracted >= stack.getCount()) {
					break;
				}
			}
		}

		return extracted > 0 ? stack.copyWithCount(extracted) : ItemStack.EMPTY;
	}

	@Override
	public void registerListeners(Consumer<ItemStackKey> onAddStackKey, Consumer<ItemStackKey> onRemoveStackKey, Runnable onAddFirstEmptySlot,
			Runnable onRemoveLastEmptySlot) {
		this.onAddStackKey = onAddStackKey;
		this.onRemoveStackKey = onRemoveStackKey;
		this.onAddFirstEmptySlot = onAddFirstEmptySlot;
		this.onRemoveLastEmptySlot = onRemoveLastEmptySlot;
	}

	@Override
	public void unregisterStackKeyListeners() {
		onAddStackKey = sk -> {
		};
		onRemoveStackKey = sk -> {
		};
	}

	@Override
	public boolean hasEmptySlots() {
		return shouldInsertIntoEmpty.getAsBoolean() && !emptySlots.isEmpty();
	}

	private ItemStack handleOverflow(UnaryOperator<ItemStack> slotOverflowHandler, UnaryOperator<ItemStack> storageOverflowHandler, ItemStackKey stackKey,
			ItemStack remainingStack) {
		boolean hasOneFullStackOfItem = hasOneFullStackOfItem(stackKey);
		return handleOverflow(slotOverflowHandler, storageOverflowHandler, stackKey, remainingStack, hasOneFullStackOfItem);
	}

	private boolean hasOneFullStackOfItem(ItemStackKey stackKey) {
		return fullStackSlots.containsKey(stackKey) && !fullStackSlots.get(stackKey).isEmpty();
	}

	private ItemStack handleOverflow(UnaryOperator<ItemStack> slotOverflowHandler, UnaryOperator<ItemStack> storageOverflowHandler, ItemStackKey stackKey,
			ItemStack remainingStack, boolean hasOneFullSlotOfItem) {
		if (hasOneFullSlotOfItem) {
			if (emptySlots.isEmpty() && !partiallyFilledStackSlots.containsKey(stackKey)) {
				remainingStack = storageOverflowHandler.apply(remainingStack);
				if (remainingStack.isEmpty()) {
					return remainingStack;
				}
			}
			remainingStack = slotOverflowHandler.apply(remainingStack);
		}
		return remainingStack;
	}

	private ItemStack insertIntoSlotsThatMatchStack(IItemHandlerInserter inserter, ItemStack stack, boolean simulate, ItemStackKey stackKey) {
		ItemStack remainingStack = stack;

		Set<Integer> slots = partiallyFilledStackSlots.get(stackKey);
		if (slots == null || slots.isEmpty()) {
			return remainingStack;
		}

		int sizeBefore = slots.size();
		int i = 0;
		// Always taking first element here and iterating while not empty as iterating using iterator would produce CME due to void/compacting reacting to
		// inserts
		// and going into this logic as well and because of that causing collection to be updated outside of first level iterator. The increment is here just
		// in case updating cache fails to prevent infinite loop
		while (partiallyFilledStackSlots.get(stackKey) != null && !partiallyFilledStackSlots.get(stackKey).isEmpty() && i++ < sizeBefore) {
			int matchingSlot = partiallyFilledStackSlots.get(stackKey).iterator().next();
			remainingStack = inserter.insertItem(matchingSlot, remainingStack, simulate);
			if (remainingStack.isEmpty()) {
				break;
			}
		}
		return remainingStack;
	}

	private ItemStack insertIntoEmptySlots(IItemHandlerInserter inserter, ItemStack stack, boolean simulate) {
		ItemStack remainingStack = stack;
		remainingStack = insertIntoEmptyMemorySlots(inserter, simulate, remainingStack);
		remainingStack = insertIntoEmptyFilterSlots(inserter, simulate, remainingStack);
		if (shouldInsertIntoEmpty.getAsBoolean() && !remainingStack.isEmpty()) {
			int sizeBefore = emptySlots.size();
			int i = 0;
			// Always taking first element here and iterating while not empty as iterating using iterator would produce CME due to void/compacting reacting to
			// inserts
			// and going into this logic as well and because of that causing collection to be updated outside of first level iterator. The increment is here
			// just
			// in case updating cache fails to prevent infinite loop
			while (!emptySlots.isEmpty() && i++ < sizeBefore) {
				Iterator<Integer> it = emptySlots.iterator();
				int slot = it.next();
				while (memorySettings.isSlotSelected(slot)) {
					if (!it.hasNext()) {
						return remainingStack;
					}
					slot = it.next();
				}
				while (filterItemSlots.containsSlot(slot)) {
					if (!it.hasNext()) {
						return remainingStack;
					}
					slot = it.next();
				}

				remainingStack = inserter.insertItem(slot, remainingStack, simulate);
				if (remainingStack.isEmpty()) {
					break;
				}
			}
		}

		return remainingStack;
	}

	private ItemStack insertIntoEmptyFilterSlots(IItemHandlerInserter inserter, boolean simulate, ItemStack remainingStack) {
		Item item = remainingStack.getItem();
		if (filterItemSlots.containsValue(item)) {
			for (int filterSlot : filterItemSlots.getSlots(item)) {
				if (emptySlots.contains(filterSlot)) {
					remainingStack = inserter.insertItem(filterSlot, remainingStack, simulate);
					if (remainingStack.isEmpty()) {
						break;
					}
				}
			}
		}
		return remainingStack;
	}

	private ItemStack insertIntoEmptyMemorySlots(IItemHandlerInserter inserter, boolean simulate, ItemStack stack) {
		ItemStack remainingStack = stack;
		Map<Item, Set<Integer>> memoryFilterItemSlots = memorySettings.getFilterItemSlots();
		Item item = remainingStack.getItem();
		if (memoryFilterItemSlots.containsKey(item)) {
			for (int memorySlot : memoryFilterItemSlots.get(item)) {
				if (emptySlots.contains(memorySlot)) {
					remainingStack = inserter.insertItem(memorySlot, remainingStack, simulate);
					if (remainingStack.isEmpty()) {
						break;
					}
				}
			}
		}

		Map<Integer, Set<Integer>> memoryFilterStackSlots = memorySettings.getFilterStackSlots();
		if (!memoryFilterStackSlots.isEmpty()) {
			int stackHash = ItemStack.hashItemAndComponents(remainingStack);
			if (memoryFilterStackSlots.containsKey(stackHash)) {
				for (int memorySlot : memoryFilterStackSlots.get(stackHash)) {
					if (emptySlots.contains(memorySlot)) {
						remainingStack = inserter.insertItem(memorySlot, remainingStack, simulate);
						if (remainingStack.isEmpty()) {
							break;
						}
					}
				}
			}
		}
		return remainingStack;
	}

	@Override
	public int getFirstMatchingSlot(ItemStackKey stackKey) {
		Set<Integer> slots = partiallyFilledStackSlots.get(stackKey);
		if (slots != null && !slots.isEmpty()) {
			return slots.iterator().next();
		}
		slots = fullStackSlots.get(stackKey);
		if (slots != null && !slots.isEmpty()) {
			return slots.iterator().next();
		}
		return -1;
	}
}

package net.p3pp3rf1y.sophisticatedcore.upgrades;

import net.minecraft.core.NonNullList;
import net.minecraft.core.component.DataComponentType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.tags.TagKey;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.ItemContainerContents;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.p3pp3rf1y.sophisticatedcore.util.FilterItemStackHandler;
import net.p3pp3rf1y.sophisticatedcore.util.InventoryHelper;
import net.p3pp3rf1y.sophisticatedcore.util.ItemStackHelper;

import javax.annotation.Nullable;

import java.util.*;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.IntConsumer;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class FilterLogic {
	protected final ItemStack upgrade;
	protected final Consumer<ItemStack> saveHandler;
	protected final DeferredHolder<DataComponentType<?>, DataComponentType<FilterAttributes>> filterAttributesComponent;
	private final int defaultFilterSlotCount;
	private final Predicate<ItemStack> isItemValid;
	@Nullable
	protected Set<TagKey<Item>> tagKeys = null;
	private ObservableFilterItemStackHandler filterHandler = null;
	private boolean emptyAllowListMatchesEverything = false;
	private boolean allowListDefault = false;

	@Nullable
	private FilterAttributes emptyAttributes = null;

	public FilterLogic(ItemStack upgrade, Consumer<ItemStack> saveHandler, int defaultFilterSlotCount,
			DeferredHolder<DataComponentType<?>, DataComponentType<FilterAttributes>> filterAttributesComponent) {
		this(upgrade, saveHandler, defaultFilterSlotCount, s -> true, filterAttributesComponent);
	}

	public FilterLogic(ItemStack upgrade, Consumer<ItemStack> saveHandler, int defaultFilterSlotCount, Predicate<ItemStack> isItemValid,
			DeferredHolder<DataComponentType<?>, DataComponentType<FilterAttributes>> filterAttributesComponent) {
		this.upgrade = upgrade;
		this.saveHandler = saveHandler;
		this.filterAttributesComponent = filterAttributesComponent;
		this.defaultFilterSlotCount = defaultFilterSlotCount;
		this.isItemValid = isItemValid;
	}

	public void setEmptyAllowListMatchesEverything() {
		emptyAllowListMatchesEverything = true;
	}

	public ObservableFilterItemStackHandler getFilterHandler() {
		if (filterHandler == null) {
			ItemContainerContents filterItemContents = getAttributes().filterItems();
			NonNullList<ItemStack> filterItems = NonNullList.withSize(filterItemContents.getSlots(), ItemStack.EMPTY);
			filterItemContents.copyInto(filterItems);

			int filterSlotCount = Math.max(filterItems.size(), defaultFilterSlotCount);
			filterHandler = new ObservableFilterItemStackHandler(filterSlotCount);
			filterHandler.initFilters(filterItems);
		}

		return filterHandler;
	}

	public boolean matchesFilter(ItemStack stack) {
		if (isAllowList()) {
			if (getPrimaryMatch() == PrimaryMatch.TAGS) {
				return isTagMatch(stack);
			} else {
				return (getFilterHandler().hasOnlyEmptyFilters() && emptyAllowListMatchesEverything) || InventoryHelper.iterate(getFilterHandler(),
						(slot, filter) -> stackMatchesFilter(stack, filter), () -> false, returnValue -> returnValue);
			}
		} else {
			if (getPrimaryMatch() == PrimaryMatch.TAGS) {
				return !isTagMatch(stack);
			} else {
				return getFilterHandler().hasOnlyEmptyFilters() || InventoryHelper.iterate(getFilterHandler(),
						(slot, filter) -> !stackMatchesFilter(stack, filter), () -> true, returnValue -> !returnValue);
			}
		}
	}

	private boolean isTagMatch(ItemStack stack) {
		if (shouldMatchAnyTag()) {
			return anyTagMatches(stack.getTags());
		}
		return allTagsMatch(stack.getTags());
	}

	private boolean allTagsMatch(Stream<TagKey<Item>> tagsStream) {
		if (tagKeys == null) {
			initTags();
		}
		Set<TagKey<Item>> tags = tagsStream.collect(Collectors.toSet());
		for (TagKey<Item> tagName : tagKeys) {
			if (!tags.contains(tagName)) {
				return false;
			}
		}
		return true;
	}

	private boolean anyTagMatches(Stream<TagKey<Item>> tags) {
		if (tagKeys == null) {
			initTags();
		}
		return tags.anyMatch(tagKeys::contains);
	}

	protected FilterAttributes getAttributes() {
		return upgrade.getOrDefault(filterAttributesComponent, getEmptyAttributes());
	}

	private FilterAttributes getEmptyAttributes() {
		if (emptyAttributes == null) {
			emptyAttributes = new FilterAttributes(Collections.emptySet(), allowListDefault, false, false, PrimaryMatch.ITEM, true, ItemContainerContents.EMPTY,
					false, false);
		}
		return emptyAttributes;
	}

	protected void setAttributes(Function<FilterAttributes, FilterAttributes> setter) {
		upgrade.set(filterAttributesComponent, setter.apply(getAttributes()));
	}

	public void setAllowByDefault(boolean allowListDefault) {
		this.allowListDefault = allowListDefault;
		if (!upgrade.has(filterAttributesComponent)) {
			emptyAttributes = null;
		}
	}

	protected void save() {
		saveHandler.accept(upgrade);
	}

	public boolean stackMatchesFilter(ItemStack stack, ItemStack filter) {
		if (filter.isEmpty()) {
			return false;
		}

		PrimaryMatch primaryMatch = getPrimaryMatch();
		if (primaryMatch == PrimaryMatch.MOD) {
			if (!BuiltInRegistries.ITEM.getKey(stack.getItem()).getNamespace().equals(BuiltInRegistries.ITEM.getKey(filter.getItem()).getNamespace())) {
				return false;
			}
		} else if (primaryMatch == PrimaryMatch.ITEM && stack.getItem() != filter.getItem()) {
			return false;
		}

		if (shouldMatchDurability() && stack.getDamageValue() != filter.getDamageValue()) {
			return false;
		}

		return !shouldMatchComponents() || ItemStackHelper.areItemStackComponentsEqualIgnoreDurability(stack, filter);
	}

	public Set<TagKey<Item>> getTagKeys() {
		if (tagKeys == null) {
			initTags();
		}
		return Collections.unmodifiableSet(tagKeys);
	}

	public void addTag(TagKey<Item> tagName) {
		if (tagKeys == null) {
			initTags();
		}
		tagKeys.add(tagName);
		serializeTags();
		save();
	}

	private void serializeTags() {
		if (tagKeys == null) {
			return;
		}
		setAttributes(contents -> contents.setTagKeys(tagKeys));
	}

	public void removeTagName(TagKey<Item> tagName) {
		if (tagKeys == null) {
			initTags();
		}
		tagKeys.remove(tagName);
		serializeTags();
		save();
	}

	protected void initTags() {
		tagKeys = new TreeSet<>(Comparator.comparing(TagKey::location));
		tagKeys.addAll(getAttributes().tagKeys());
	}

	public void setAllowList(boolean isAllowList) {
		setAttributes(contents -> contents.setAllowList(isAllowList));
		save();
	}

	public boolean isAllowList() {
		return getAttributes().isAllowList();
	}

	public boolean shouldMatchDurability() {
		return getAttributes().matchDurability();
	}

	public void setMatchDurability(boolean matchDurability) {
		setAttributes(contents -> contents.setMatchDurability(matchDurability));
		save();
	}

	public void setMatchComponents(boolean matchComponents) {
		setAttributes(contents -> contents.setMatchComponents(matchComponents));
		save();
	}

	public boolean shouldMatchComponents() {
		return getAttributes().matchComponents();
	}

	public void setPrimaryMatch(PrimaryMatch primaryMatch) {
		setAttributes(contents -> contents.setPrimaryMatch(primaryMatch));
		save();
	}

	public PrimaryMatch getPrimaryMatch() {
		return getAttributes().primaryMatch();
	}

	public boolean shouldMatchAnyTag() {
		return getAttributes().matchAnyTag();
	}

	public void setMatchAnyTag(boolean matchAnyTag) {
		setAttributes(contents -> contents.setMatchAnyTag(matchAnyTag));
		save();
	}

	public DeferredHolder<DataComponentType<?>, DataComponentType<FilterAttributes>> getAttributesComponent() {
		return filterAttributesComponent;
	}

	public class ObservableFilterItemStackHandler extends FilterItemStackHandler {
		private IntConsumer onSlotChange = s -> {
		};
		public ObservableFilterItemStackHandler(int filterSlotCount) {
			super(filterSlotCount);
		}

		@Override
		protected void onContentsChanged(int slot) {
			super.onContentsChanged(slot);
			setAttributes(contents -> contents.setFilterItem(slot, stacks.get(slot)));
			save();
			onSlotChange.accept(slot);
		}

		public void setOnSlotChange(IntConsumer onSlotChange) {
			this.onSlotChange = onSlotChange;
		}

		@Override
		public boolean isItemValid(int slot, ItemStack stack) {
			return stack.isEmpty() || (doesNotContain(stack) && isItemValid.test(stack));
		}

		private boolean doesNotContain(ItemStack stack) {
			return !InventoryHelper.hasItem(this, s -> ItemStack.isSameItemSameComponents(s, stack));
		}

		public void initFilters(List<ItemStack> filterItems) {
			for (int slot = 0; slot < filterItems.size(); slot++) {
				setStackInSlot(slot, filterItems.get(slot).copy());
			}
			onLoad();
		}
	}
}

package net.p3pp3rf1y.sophisticatedcore.upgrades;

import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;
import net.neoforged.fml.util.thread.SidedThreadGroups;
import net.neoforged.neoforge.items.ItemStackHandler;
import net.p3pp3rf1y.sophisticatedcore.api.IStorageWrapper;
import net.p3pp3rf1y.sophisticatedcore.renderdata.RenderInfo;
import net.p3pp3rf1y.sophisticatedcore.renderdata.TankPosition;
import net.p3pp3rf1y.sophisticatedcore.util.InventoryHelper;
import net.p3pp3rf1y.sophisticatedcore.util.RegistryHelper;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;

public class UpgradeHandler extends ItemStackHandler {
	public static final String UPGRADE_INVENTORY_TAG = "upgradeInventory";
	private final IStorageWrapper storageWrapper;
	private final Runnable contentsSaveHandler;
	private final Runnable onInvalidateUpgradeCaches;
	private final CompoundTag contentsNbt;
	@Nullable
	private Runnable refreshCallBack = null;
	private final Set<Runnable> refreshCallbacks = Collections.newSetFromMap(new IdentityHashMap<>());
	private final Map<Integer, IUpgradeWrapper> slotWrappers = new LinkedHashMap<>();
	private final Map<UpgradeType<? extends IUpgradeWrapper>, List<? extends IUpgradeWrapper>> typeWrappers = new HashMap<>();
	private boolean justSavingNbtChange = false;
	private boolean wrappersInitialized = false;
	private boolean typeWrappersInitialized = false;
	@Nullable
	private IUpgradeWrapperAccessor wrapperAccessor = null;
	private boolean persistent = true;
	private final Map<Class<? extends IUpgradeWrapper>, Consumer<? extends IUpgradeWrapper>> upgradeDefaultsHandlers = new HashMap<>();

	public UpgradeHandler(int numberOfUpgradeSlots, IStorageWrapper storageWrapper, CompoundTag contentsNbt, Runnable contentsSaveHandler,
			Runnable onInvalidateUpgradeCaches) {
		super(numberOfUpgradeSlots);
		this.contentsNbt = contentsNbt;
		this.storageWrapper = storageWrapper;
		this.contentsSaveHandler = contentsSaveHandler;
		this.onInvalidateUpgradeCaches = onInvalidateUpgradeCaches;
		RegistryHelper.getRegistryAccess().ifPresent(registryAccess -> deserializeNBT(registryAccess, contentsNbt.getCompound(UPGRADE_INVENTORY_TAG)));
		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER && storageWrapper.getRenderInfo().getUpgradeItems().size() != getSlots()) {
			setRenderUpgradeItems();
		}
	}

	public <T extends IUpgradeWrapper> void registerUpgradeDefaultsHandler(Class<T> upgradeClass, Consumer<T> defaultsHandler) {
		upgradeDefaultsHandlers.put(upgradeClass, defaultsHandler);
	}

	@Override
	public boolean isItemValid(int slot, @Nonnull ItemStack stack) {
		return stack.isEmpty() || stack.getItem() instanceof IUpgradeItem;
	}

	@Override
	protected void onContentsChanged(int slot) {
		super.onContentsChanged(slot);
		if (persistent) {
			saveInventory();
			contentsSaveHandler.run();
		}
		if (!justSavingNbtChange) {
			refreshUpgradeWrappers();
			setRenderUpgradeItems();
		}
	}

	public void setRenderUpgradeItems() {
		List<ItemStack> upgradeItems = new ArrayList<>();
		InventoryHelper.iterate(this, (upgradeSlot, upgrade) -> upgradeItems.add(upgrade.copyWithCount(1)));
		storageWrapper.getRenderInfo().setUpgradeItems(upgradeItems);
	}

	@Override
	public void setSize(int size) {
		super.setSize(stacks.size());
	}

	public void saveInventory() {
		RegistryHelper.getRegistryAccess().ifPresent(registryAccess -> contentsNbt.put(UPGRADE_INVENTORY_TAG, serializeNBT(registryAccess)));
	}

	public void setPersistent(boolean persistent) {
		this.persistent = persistent;
	}

	public void setRefreshCallBack(Runnable refreshCallBack) {
		this.refreshCallBack = refreshCallBack;
	}

	public void removeRefreshCallback() {
		refreshCallBack = null;
	}

	public void addRefreshCallback(Runnable refreshCallback) {
		refreshCallbacks.add(refreshCallback);
	}

	public void removeRefreshCallback(Runnable refreshCallback) {
		refreshCallbacks.remove(refreshCallback);
	}

	private void initializeWrappers() {
		if (wrappersInitialized) {
			return;
		}
		wrappersInitialized = true;
		slotWrappers.clear();
		typeWrappers.clear();
		if (wrapperAccessor != null) {
			wrapperAccessor.clearCache();
		}

		InventoryHelper.iterate(this, (slot, upgrade) -> {
			if (upgrade.isEmpty() || !(upgrade.getItem() instanceof IUpgradeItem<?>)) {
				return;
			}
			UpgradeType<?> type = ((IUpgradeItem<?>) upgrade.getItem()).getType();
			IUpgradeWrapper wrapper = type.create(storageWrapper, upgrade, upgradeStack -> {
				justSavingNbtChange = true;
				setStackInSlot(slot, upgradeStack);
				justSavingNbtChange = false;
			});
			setUpgradeDefaults(wrapper);
			slotWrappers.put(slot, wrapper);
		});

		initRenderInfoCallbacks(false);
	}

	@Nonnull
	@Override
	public ItemStack insertItem(int slot, @Nonnull ItemStack stack, boolean simulate) {
		ItemStack result = super.insertItem(slot, stack, simulate);
		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER && result.isEmpty() && !stack.isEmpty()) {
			onUpgradeAdded(slot);
		}

		return result;
	}

	private void onUpgradeAdded(int slot) {
		Map<Integer, IUpgradeWrapper> wrappers = getSlotWrappers();
		if (wrappers.containsKey(slot)) {
			wrappers.get(slot).onAdded();
		}
	}

	private void setUpgradeDefaults(IUpgradeWrapper wrapper) {
		getUpgradeDefaultsHandler(wrapper).accept(wrapper);
	}

	private <T extends IUpgradeWrapper> Consumer<T> getUpgradeDefaultsHandler(T wrapper) {
		// noinspection unchecked
		return (Consumer<T>) upgradeDefaultsHandlers.getOrDefault(wrapper.getClass(), w -> {
		});
	}

	@Override
	public void setStackInSlot(int slot, @Nonnull ItemStack stack) {
		ItemStack originalStack = getStackInSlot(slot);
		Map<Integer, IUpgradeWrapper> wrappers = getSlotWrappers();
		boolean itemsDiffer = !ItemStack.isSameItemSameComponents(originalStack, stack);
		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER && itemsDiffer && wrappers.containsKey(slot)) {
			wrappers.get(slot).onBeforeRemoved();
		}

		super.setStackInSlot(slot, stack);

		if (Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER && itemsDiffer) {
			onUpgradeAdded(slot);
		}
	}

	@Override
	public ItemStack extractItem(int slot, int amount, boolean simulate) {
		if (!simulate && Thread.currentThread().getThreadGroup() == SidedThreadGroups.SERVER) {
			ItemStack slotStack = getStackInSlot(slot);
			if (persistent && !slotStack.isEmpty() && amount == 1) {
				Map<Integer, IUpgradeWrapper> wrappers = getSlotWrappers();
				if (wrappers.containsKey(slot)) {
					wrappers.get(slot).onBeforeRemoved();
				}
			}
		}
		return super.extractItem(slot, amount, simulate);
	}

	private void initializeTypeWrappers() {
		if (typeWrappersInitialized) {
			return;
		}
		initializeWrappers();
		typeWrappersInitialized = true;

		typeWrappers.clear();
		slotWrappers.values().forEach(wrapper -> {
			if (wrapper.getUpgradeStack().getItem() instanceof IUpgradeItem<?> upgradeItem) {
				UpgradeType<?> type = upgradeItem.getType();
				if (wrapper.isEnabled() && (!(wrapper instanceof ITickableUpgrade) || storageWrapper.isUpgradeRunnable(wrapper.getUpgradeStack()))) {
					addTypeWrapper(type, wrapper);
				}
			}
		});

		initRenderInfoCallbacks(false);
	}

	private <T extends IUpgradeWrapper> void addTypeWrapper(UpgradeType<?> type, T wrapper) {
		// noinspection unchecked
		((List<T>) typeWrappers.computeIfAbsent(type, t -> new ArrayList<>())).add(wrapper);
	}

	public <T extends IUpgradeWrapper> List<T> getTypeWrappers(UpgradeType<T> type) {
		initializeTypeWrappers();
		// noinspection unchecked
		return (List<T>) typeWrappers.getOrDefault(type, Collections.emptyList());
	}

	public <T extends IUpgradeWrapper> boolean hasUpgrade(UpgradeType<T> type) {
		return !getTypeWrappers(type).isEmpty();
	}

	public <T> List<T> getWrappersThatImplement(Class<T> upgradeClass) {
		initializeWrappers();
		return getWrapperAccessor().getWrappersThatImplement(upgradeClass);
	}

	private IUpgradeWrapperAccessor getWrapperAccessor() {
		if (wrapperAccessor == null) {
			IUpgradeWrapperAccessor accessor = new Accessor(this);
			for (IUpgradeAccessModifier upgrade : getListOfWrappersThatImplement(IUpgradeAccessModifier.class)) {
				accessor = upgrade.wrapAccessor(accessor);
			}
			wrapperAccessor = accessor;
		}
		return wrapperAccessor;
	}

	public <T> List<T> getWrappersThatImplementFromMainStorage(Class<T> upgradeClass) {
		initializeWrappers();
		return getWrapperAccessor().getWrappersThatImplementFromMainStorage(upgradeClass);
	}

	public <T> List<T> getListOfWrappersThatImplement(Class<T> uc) {
		List<T> ret = new ArrayList<>();
		for (IUpgradeWrapper wrapper : slotWrappers.values()) {
			if (wrapper.isEnabled() && uc.isInstance(wrapper)) {
				// noinspection unchecked
				ret.add((T) wrapper);
			}
		}
		return ret;
	}

	public Map<Integer, IUpgradeWrapper> getSlotWrappers() {
		initializeWrappers();
		return slotWrappers;
	}

	public void copyTo(UpgradeHandler otherHandler) {
		InventoryHelper.copyTo(this, otherHandler);
	}

	public void refreshWrappersThatImplementAndTypeWrappers() {
		typeWrappersInitialized = false;
		onBeforeDeconstruct();
		onInvalidateUpgradeCaches.run();
		notifyRefreshCallbacks();
	}

	public void refreshUpgradeWrappers() {
		if (!wrappersInitialized && !typeWrappersInitialized) {
			return;
		}

		wrappersInitialized = false;
		typeWrappersInitialized = false;
		onBeforeDeconstruct();
		notifyRefreshCallbacks();
		onInvalidateUpgradeCaches.run();

		initRenderInfoCallbacks(true);
	}

	public void onBeforeDeconstruct() {
		if (wrapperAccessor != null) {
			wrapperAccessor.onBeforeDeconstruct();
			wrapperAccessor = null;
		}
	}

	public void notifyRefreshCallbacks() {
		if (refreshCallBack != null) {
			refreshCallBack.run();
		}
		List.copyOf(refreshCallbacks).forEach(Runnable::run);
	}

	private void initRenderInfoCallbacks(boolean forceUpdateRenderInfo) {
		RenderInfo renderInfo = storageWrapper.getRenderInfo();
		if (forceUpdateRenderInfo) {
			renderInfo.resetUpgradeInfo(false);
		}

		initTankRenderInfoCallbacks(forceUpdateRenderInfo, renderInfo);
		initBatteryRenderInfoCallbacks(forceUpdateRenderInfo, renderInfo);
	}

	private void initBatteryRenderInfoCallbacks(boolean forceUpdateRenderInfo, RenderInfo renderInfo) {
		getSlotWrappers().forEach((slot, wrapper) -> {
			if (wrapper instanceof IRenderedBatteryUpgrade batteryWrapper) {
				batteryWrapper.setBatteryRenderInfoUpdateCallback(renderInfo::setBatteryRenderInfo);
				if (forceUpdateRenderInfo) {
					batteryWrapper.forceUpdateBatteryRenderInfo();
				}
			}
		});
	}

	private void initTankRenderInfoCallbacks(boolean forceUpdateRenderInfo, RenderInfo renderInfo) {
		AtomicBoolean singleTankRight = new AtomicBoolean(false);
		List<IRenderedTankUpgrade> tankRenderWrappers = new ArrayList<>();
		int minRightSlot = getSlots() / 2;
		getSlotWrappers().forEach((slot, wrapper) -> {
			if (wrapper instanceof IRenderedTankUpgrade tankUpgrade) {
				tankRenderWrappers.add(tankUpgrade);
				if (slot >= minRightSlot) {
					singleTankRight.set(true);
				}
			}
		});

		TankPosition currentTankPos = tankRenderWrappers.size() == 1 && singleTankRight.get() ? TankPosition.RIGHT : TankPosition.LEFT;
		for (IRenderedTankUpgrade tankRenderWrapper : tankRenderWrappers) {
			TankPosition finalCurrentTankPos = currentTankPos;
			tankRenderWrapper.setTankRenderInfoUpdateCallback(tankRenderInfo -> renderInfo.setTankRenderInfo(finalCurrentTankPos, tankRenderInfo));
			if (forceUpdateRenderInfo) {
				tankRenderWrapper.forceUpdateTankRenderInfo();
			}
			currentTankPos = TankPosition.RIGHT;
		}
	}

	public void increaseSize(int diff) {
		NonNullList<ItemStack> previousStacks = stacks;
		stacks = NonNullList.withSize(previousStacks.size() + diff, ItemStack.EMPTY);
		for (int slot = 0; slot < previousStacks.size(); slot++) {
			stacks.set(slot, previousStacks.get(slot));
		}
		saveInventory();
		setRenderUpgradeItems();
	}

	@Override
	public int getSlotLimit(int slot) {
		return 1;
	}

	private static class Accessor implements IUpgradeWrapperAccessor {
		private final Map<Class<?>, List<?>> interfaceWrappers = new ConcurrentHashMap<>();

		private final UpgradeHandler upgradeHandler;

		public Accessor(UpgradeHandler upgradeHandler) {
			this.upgradeHandler = upgradeHandler;
		}

		@Override
		public <T> List<T> getWrappersThatImplement(Class<T> upgradeClass) {
			// noinspection unchecked
			return (List<T>) interfaceWrappers.computeIfAbsent(upgradeClass, upgradeHandler::getListOfWrappersThatImplement);
		}

		@Override
		public <T> List<T> getWrappersThatImplementFromMainStorage(Class<T> upgradeClass) {
			// noinspection unchecked
			return (List<T>) interfaceWrappers.computeIfAbsent(upgradeClass, upgradeHandler::getListOfWrappersThatImplement);
		}

		@Override
		public void clearCache() {
			interfaceWrappers.clear();
		}
	}
}

